// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/balances/me", wrapper.GetMyBalances)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/budgets", wrapper.ListBudgetCategories)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/budgets", wrapper.CreateBudgetCategory)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/budgets/overview", wrapper.GetBudgetOverview)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/budgets/{budgetId}", wrapper.DeleteBudgetCategory)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/budgets/{budgetId}", wrapper.UpdateBudgetCategory)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/expenses", wrapper.ListExpenses)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/expenses", wrapper.CreateExpense)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/expenses/{expenseId}", wrapper.DeleteExpense)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/expenses/{expenseId}", wrapper.GetExpense)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/expenses/{expenseId}", wrapper.UpdateExpense)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/households", wrapper.DeleteHousehold)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/households", wrapper.CreateHousehold)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/households/invite-code/regenerate", wrapper.RegenerateInviteCode)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/households/join", wrapper.JoinHousehold)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/households/leave", wrapper.LeaveHousehold)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/households/me", wrapper.GetMyHousehold)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/households/members/{userId}", wrapper.RemoveHouseholdMember)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/reports", wrapper.ListReports)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/reports/{month}/{year}", wrapper.GetReport)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/reports/{month}/{year}/close", wrapper.CloseReport)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/reports/{month}/{year}/reopen", wrapper.ReopenReport)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/users/me", wrapper.GetUsersMe)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/users/me", wrapper.PatchUsersMe)
	})

	return r
}

