// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Get current user's live balance summary for a given month
	// (GET /balances/me)
	GetMyBalances(ctx context.Context, request GetMyBalancesRequestObject) (GetMyBalancesResponseObject, error)
	// List budget categories for the current household
	// (GET /budgets)
	ListBudgetCategories(ctx context.Context, request ListBudgetCategoriesRequestObject) (ListBudgetCategoriesResponseObject, error)
	// Create a budget category
	// (POST /budgets)
	CreateBudgetCategory(ctx context.Context, request CreateBudgetCategoryRequestObject) (CreateBudgetCategoryResponseObject, error)
	// Get budget overview for the current month
	// (GET /budgets/overview)
	GetBudgetOverview(ctx context.Context, request GetBudgetOverviewRequestObject) (GetBudgetOverviewResponseObject, error)
	// Soft-delete a budget category
	// (DELETE /budgets/{budgetId})
	DeleteBudgetCategory(ctx context.Context, request DeleteBudgetCategoryRequestObject) (DeleteBudgetCategoryResponseObject, error)
	// Update a budget category
	// (PATCH /budgets/{budgetId})
	UpdateBudgetCategory(ctx context.Context, request UpdateBudgetCategoryRequestObject) (UpdateBudgetCategoryResponseObject, error)
	// List expenses for the current household
	// (GET /expenses)
	ListExpenses(ctx context.Context, request ListExpensesRequestObject) (ListExpensesResponseObject, error)
	// Create an expense with splits
	// (POST /expenses)
	CreateExpense(ctx context.Context, request CreateExpenseRequestObject) (CreateExpenseResponseObject, error)
	// Delete an expense
	// (DELETE /expenses/{expenseId})
	DeleteExpense(ctx context.Context, request DeleteExpenseRequestObject) (DeleteExpenseResponseObject, error)
	// Get expense detail with splits
	// (GET /expenses/{expenseId})
	GetExpense(ctx context.Context, request GetExpenseRequestObject) (GetExpenseResponseObject, error)
	// Update an expense
	// (PATCH /expenses/{expenseId})
	UpdateExpense(ctx context.Context, request UpdateExpenseRequestObject) (UpdateExpenseResponseObject, error)
	// Delete the current user's household (owner only)
	// (DELETE /households)
	DeleteHousehold(ctx context.Context, request DeleteHouseholdRequestObject) (DeleteHouseholdResponseObject, error)
	// Create a new household
	// (POST /households)
	CreateHousehold(ctx context.Context, request CreateHouseholdRequestObject) (CreateHouseholdResponseObject, error)
	// Regenerate the household invite code (owner only)
	// (POST /households/invite-code/regenerate)
	RegenerateInviteCode(ctx context.Context, request RegenerateInviteCodeRequestObject) (RegenerateInviteCodeResponseObject, error)
	// Join a household via invite code
	// (POST /households/join)
	JoinHousehold(ctx context.Context, request JoinHouseholdRequestObject) (JoinHouseholdResponseObject, error)
	// Leave the current household (non-owner only)
	// (POST /households/leave)
	LeaveHousehold(ctx context.Context, request LeaveHouseholdRequestObject) (LeaveHouseholdResponseObject, error)
	// Get the current user's household with members
	// (GET /households/me)
	GetMyHousehold(ctx context.Context, request GetMyHouseholdRequestObject) (GetMyHouseholdResponseObject, error)
	// Remove a member from the household (owner only)
	// (DELETE /households/members/{userId})
	RemoveHouseholdMember(ctx context.Context, request RemoveHouseholdMemberRequestObject) (RemoveHouseholdMemberResponseObject, error)
	// List months with expenses (dynamic reports)
	// (GET /reports)
	ListReports(ctx context.Context, request ListReportsRequestObject) (ListReportsResponseObject, error)
	// Get a dynamically computed report for a given month
	// (GET /reports/{month}/{year})
	GetReport(ctx context.Context, request GetReportRequestObject) (GetReportResponseObject, error)
	// Close a monthly report (owner only)
	// (POST /reports/{month}/{year}/close)
	CloseReport(ctx context.Context, request CloseReportRequestObject) (CloseReportResponseObject, error)
	// Reopen a closed monthly report (owner only)
	// (POST /reports/{month}/{year}/reopen)
	ReopenReport(ctx context.Context, request ReopenReportRequestObject) (ReopenReportResponseObject, error)
	// Get current user profile
	// (GET /users/me)
	GetUsersMe(ctx context.Context, request GetUsersMeRequestObject) (GetUsersMeResponseObject, error)
	// Update current user preferences
	// (PATCH /users/me)
	PatchUsersMe(ctx context.Context, request PatchUsersMeRequestObject) (PatchUsersMeResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

